// Generated by sel-pull (Shared Element Library): do not edit, it is replaced by the next "sel-pull firebase".
//
// The Firebase config the emulators run with. Hosting serves public/ with the headers of firebase.json, and an enforced Content-Security-Policy
// there would block the page's own connections to the Auth and Firestore emulators (they are not on the allowed list of the live site, and
// must not be). So when firebase.json sets a Content-Security-Policy, start.mjs runs the emulators with firebase.dev.json instead: a copy of
// firebase.json whose policy also allows the emulator addresses in connect-src and frame-src. firebase.json itself is never changed, and the
// copy is rewritten at every start (it is git-ignored). The same copy moves the Hosting emulator a few thousand ports up, behind the cache-less proxy
// of dev-proxy.mjs that listens on the address the app is opened at (see devRuntime below for why).
export const DEV_CONFIG_FILE = "firebase.dev.json";

/** The http:// addresses of the emulators in firebase.json ("emulators"), under both names a browser may use for this machine. */
export function emulatorOrigins(config) {
  const origins = [];
  for (const [name, emulator] of Object.entries(config.emulators || {})) {
    if (!emulator || typeof emulator !== "object" || !emulator.port || name === "ui") continue;
    for (const host of new Set(["localhost", "127.0.0.1", emulator.host].filter(Boolean))) origins.push(`http://${host}:${emulator.port}`);
  }
  return origins;
}

/** The policy with `origins` added to connect-src and frame-src; everything else is exactly what is enforced live. */
export function withEmulatorOrigins(policy, origins) {
  const extra = origins.join(" ");
  const add = (csp, directive) => {
    const re = new RegExp(`(${directive} [^;]*)`);
    return re.test(csp) ? csp.replace(re, `$1 ${extra}`) : `${csp}; ${directive} 'self' ${extra}`;
  };
  return add(add(policy, "connect-src"), "frame-src");
}

/** The config to start the emulators with: a patched copy of `config`, or null when it has no Content-Security-Policy to patch (devRuntime is what start.mjs uses). */
export function devConfig(config) {
  const origins = emulatorOrigins(config);
  let patched = false;
  const hosting = config.hosting;
  const sections = Array.isArray(hosting) ? hosting : hosting ? [hosting] : [];
  const copy = JSON.parse(JSON.stringify(config));
  const copySections = Array.isArray(copy.hosting) ? copy.hosting : copy.hosting ? [copy.hosting] : [];
  copySections.forEach((section) => {
    for (const group of section.headers || []) {
      for (const header of group.headers || []) {
        if (String(header.key).toLowerCase() === "content-security-policy") {
          header.value = withEmulatorOrigins(header.value, origins);
          patched = true;
        }
      }
    }
  });
  return sections.length && patched ? copy : null;
}

/**
 * What start.mjs runs: { config, proxy }. `config` is the copy for the emulators: the Content-Security-Policy patched as above (when there is one), and the
 * Hosting emulator moved to another port. `proxy` is { host, port, targetPort } for dev-proxy.mjs, or null when firebase.json has no Hosting emulator.
 *
 * Why the proxy: the Hosting emulator does not apply the "headers" of firebase.json (checked on firebase-tools 15: not even a catch-all rule), so it sends no
 * Cache-Control and a browser keeps files for long. A project that is run on the same address as another one (every Firebase project uses 5000) or edited
 * between runs then serves stale scripts, which fail with module-export errors that a normal reload does not clear.
 */
export function devRuntime(config) {
  const copy = devConfig(config) || JSON.parse(JSON.stringify(config));
  const hosting = copy.emulators?.hosting;
  if (!hosting?.port) return { config: copy, proxy: null };
  const publicPort = hosting.port;
  hosting.port = publicPort + 10000 <= 65000 ? publicPort + 10000 : publicPort - 10000;
  return { config: copy, proxy: { host: hosting.host || "127.0.0.1", port: publicPort, targetPort: hosting.port } };
}
